const FEEDS = [
  {
    "source": "VnExpress",
    "url": "https://vnexpress.net/rss/tin-moi-nhat.rss"
  },
  {
    "source": "VnExpress",
    "url": "https://vnexpress.net/rss/thoi-su.rss"
  },
  {
    "source": "Tuổi Trẻ",
    "url": "https://tuoitre.vn/rss/thoi-su.rss"
  },
  {
    "source": "Thanh Niên",
    "url": "https://thanhnien.vn/rss/thoi-su.rss"
  },
  {
    "source": "Dân Trí",
    "url": "https://dantri.com.vn/rss/xa-hoi.rss"
  },
  {
    "source": "VTV",
    "url": "https://vtv.vn/trong-nuoc.rss"
  }
];

return FEEDS.map(f => ({ json: f }));

// Giữ tin trong N giờ gần nhất, mỗi lần chạy tối đa MAX_ITEMS tin
const HOURS = 6;
const MAX_ITEMS = 8;
const SOURCES = {
  'vnexpress.net': 'VnExpress',
  'tuoitre.vn': 'Tuổi Trẻ',
  'thanhnien.vn': 'Thanh Niên',
  'dantri.com.vn': 'Dân Trí',
  'vtv.vn': 'VTV',
};
const cutoff = Date.now() - HOURS * 3600 * 1000;
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const seen = new Set();
const items = [];
for (const { json } of $input.all()) {
  const link = json.link;
  if (!link || seen.has(link)) continue;
  const time = Date.parse(json.isoDate || json.pubDate || '');
  if (!time || time < cutoff) continue;
  seen.add(link);
  const host = new URL(link).hostname.replace(/^www\./, '');
  items.push({
    title: strip(json.title),
    summary: strip(json.contentSnippet || json.content || json.description).slice(0, 1500),
    link,
    source: SOURCES[host] || host,
    publishedAt: new Date(time).toISOString(),
  });
}
items.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
return items.slice(0, MAX_ITEMS).map(json => ({ json }));

